import { Badge, Drawer, Table, Text } from '@mantine/core'
import dayjs from 'dayjs'
import { formatTzs } from '../../utils/format'
import { AppIcon } from '../../components/appIcon'
import {
  estimateInstallment,
  methodLabel,
  scheduleFor,
  totalRepayable,
  type InterestMethod,
  type LoanApplication,
} from './loanApplicationsData'

// Shows the estimate for the terms typed in Loan details:
// the totals, Flat vs Reducing side by side and the month-by-month schedule.
// Read only, it always matches the form. The real schedule is generated by the backend at disbursement.

type Props = {
  opened: boolean
  onClose: () => void
  /** the terms from the form, null while amount, rate or tenure is still empty */
  application: LoanApplication | null
}

const plain = (n: number, digits = 0) =>
  n.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits })

export function LoanCalculatorDrawer({ opened, onClose, application: a }: Props) {
  return (
    <Drawer
      opened={opened}
      onClose={onClose}
      position="right"
      size="xl"
      title={
        <div className="flex items-center gap-2">
          <AppIcon name="calculator" />
          <Text fw={600}>Loan calculator</Text>
        </div>
      }
    >
      {!a || a.requestedAmount <= 0 || a.tenure <= 0 ? (
        <div className="rounded-md border border-dashed border-gray-200 px-4 py-10 text-center text-sm text-gray-500">
          Enter the requested amount, interest rate and tenure to see the calculation.
        </div>
      ) : (
        <Calculation a={a} />
      )}
    </Drawer>
  )
}

function Calculation({ a }: { a: LoanApplication }) {
  const p = a.requestedAmount
  const n = a.tenure
  const rate = a.interestRate
  const emi = estimateInstallment(a)
  const repayable = totalRepayable(a)
  const interest = repayable - p
  const rows = scheduleFor(a)
  const reducing = a.interestMethod === 'REDUCING'

  // the same terms under the other method, for the comparison
  const other: InterestMethod = reducing ? 'FLAT' : 'REDUCING'
  const otherApp = { ...a, interestMethod: other }
  const otherInterest = totalRepayable(otherApp) - p
  const saving = reducing ? otherInterest - interest : interest - otherInterest

  return (
    <div className="space-y-6">
      {/* the terms being calculated */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {[
          ['Principal (P)', formatTzs(p)],
          ['Interest rate', `${plain(rate, 2)}% a year`],
          ['Tenure (n)', `${n} months`],
          ['Method', methodLabel(a.interestMethod)],
        ].map(([label, value]) => (
          <div key={label} className="rounded-md bg-gray-50 px-3 py-2">
            <div className="text-[11px] text-gray-500">{label}</div>
            <div className="text-sm font-medium text-gray-800">{value}</div>
          </div>
        ))}
      </div>

      {/* totals and the other method */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
        {[
          ['Monthly installment', formatTzs(Math.round(emi))],
          ['Total interest', formatTzs(Math.round(interest))],
          ['Total repayable', formatTzs(Math.round(repayable))],
        ].map(([label, value]) => (
          <div key={label} className="rounded-md border border-gray-200 px-3 py-2">
            <div className="text-[11px] text-gray-500">{label}</div>
            <div className="text-base font-semibold text-gray-800">{value}</div>
          </div>
        ))}
      </div>

      <div className="rounded-md border border-gray-200 px-3 py-3">
        <Text size="sm" fw={600} mb={6}>
          Reducing balance vs Flat, same terms
        </Text>
        <Table withRowBorders={false} verticalSpacing={4} fz="xs">
          <Table.Thead>
            <Table.Tr>
              <Table.Th />
              <Table.Th ta="right">Reducing balance</Table.Th>
              <Table.Th ta="right">Flat</Table.Th>
            </Table.Tr>
          </Table.Thead>
          <Table.Tbody>
            {(() => {
              const red = reducing ? a : otherApp
              const flat = reducing ? otherApp : a
              return [
                ['Monthly installment', estimateInstallment(red), estimateInstallment(flat)],
                ['Total interest', totalRepayable(red) - p, totalRepayable(flat) - p],
                ['Total repayable', totalRepayable(red), totalRepayable(flat)],
              ].map(([label, r, f]) => (
                <Table.Tr key={label as string}>
                  <Table.Td className="text-gray-500">{label}</Table.Td>
                  <Table.Td ta="right" fw={reducing ? 600 : 400}>
                    {formatTzs(Math.round(r as number))}
                  </Table.Td>
                  <Table.Td ta="right" fw={reducing ? 400 : 600}>
                    {formatTzs(Math.round(f as number))}
                  </Table.Td>
                </Table.Tr>
              ))
            })()}
          </Table.Tbody>
        </Table>
        {saving > 0 && (
          <Text size="xs" c="dimmed" mt={6}>
            Reducing balance charges {formatTzs(Math.round(saving))} less interest on these terms.
          </Text>
        )}
      </div>

      {/* month by month */}
      <div>
        <div className="mb-2 flex items-center justify-between gap-2">
          <Text size="sm" fw={600}>
            Month-by-month schedule
          </Text>
          <Badge variant="light" color="gray" radius="sm" size="sm" tt="none">
            {methodLabel(a.interestMethod)}
          </Badge>
        </div>
        <div className="max-h-[420px] overflow-auto rounded-md border border-gray-200">
          <Table striped stickyHeader verticalSpacing={6} fz="xs">
            <Table.Thead>
              <Table.Tr>
                <Table.Th>#</Table.Th>
                <Table.Th>Due</Table.Th>
                <Table.Th ta="right">Installment</Table.Th>
                <Table.Th ta="right">Interest</Table.Th>
                <Table.Th ta="right">Principal</Table.Th>
                <Table.Th ta="right">Balance</Table.Th>
              </Table.Tr>
            </Table.Thead>
            <Table.Tbody>
              {rows.map((r) => (
                <Table.Tr key={r.id}>
                  <Table.Td>{r.installmentNo}</Table.Td>
                  <Table.Td>{dayjs(r.dueDate).format('MMM YYYY')}</Table.Td>
                  <Table.Td ta="right">{plain(r.total)}</Table.Td>
                  <Table.Td ta="right">{plain(r.interest)}</Table.Td>
                  <Table.Td ta="right">{plain(r.principal)}</Table.Td>
                  <Table.Td ta="right">{plain(r.balance)}</Table.Td>
                </Table.Tr>
              ))}
            </Table.Tbody>
          </Table>
        </div>
      </div>

      <Text size="xs" c="dimmed">
        This is an estimate from the terms above, with due dates counted from today. The backend generates the real
        schedule when the loan is disbursed, so amounts can differ by a few shillings from rounding.
      </Text>
    </div>
  )
}
